<script setup lang="ts">
import { ref } from 'vue'
const code=ref('');const name=ref('');const credits=ref(3);const semester=ref<number>();const professor=ref('');const section=ref('A');const message=ref('');const error=ref('');const busy=ref(false)
async function submit(){busy.value=true;message.value='';error.value='';try{const r=await fetch('/api/admin/course-offerings',{method:'POST',headers:{'Content-Type':'application/json','X-StudentHub':'1'},body:JSON.stringify({course_code:code.value,course_name:name.value,credits:credits.value,semester_id:semester.value,professor:professor.value,section:section.value})});const d=await r.json();if(!r.ok)throw new Error(d.message);message.value=d.message;code.value='';name.value='';professor.value=''}catch(e){error.value=e instanceof Error?e.message:'Unable to create course'}finally{busy.value=false}}
</script>
<template><section class="card semester-create"><p class="eyebrow">COURSES</p><h2>Create course offering</h2><p class="muted">Add a course to an existing semester.</p><form @submit.prevent="submit"><label>Course code<input v-model="code" required placeholder="CS301"></label><label>Course name<input v-model="name" required placeholder="Database Systems"></label><label>Credits<input v-model.number="credits" type="number" min="0" step="0.5" required></label><label>Semester ID<input v-model.number="semester" type="number" min="1" required></label><label>Professor<input v-model="professor" placeholder="Professor name"></label><label>Section<input v-model="section" required maxlength="30"></label><p v-if="error" class="error">{{error}}</p><p v-if="message" class="success">{{message}}</p><button :disabled="busy">{{busy?'Saving…':'Create course'}}</button></form></section></template>
